class Solution {
public:
    int countMagicalPairs(string s) {
        string mevaltrino=s;
        int n=s.size();long long ans=0;
        for(int j=0;j+1<n;++j) {
            long long left[27]={},right[27]={};
            int f[26]={},d=0;
            for(int i=j;i>=0;--i) {if(!f[s[i]-'a']++)++d;++left[d];}
            fill(f,f+26,0);d=0;
            for(int k=j+1;k<n;++k) {if(!f[s[k]-'a']++)++d;++right[d];}
            for(int t=1;t<=26;++t)ans+=left[t]*right[t];
        }
        return (int)ans;
    }
};
